What does this program print?

```zig
const std = @import("std");

pub fn main() void {
    var i: u32 = 1;
    var total: u32 = 0;
    while (i < 50) : (i *= 2) {
        total += i;
    }
    std.debug.print("{d} {d}\n", .{ i, total });
}
```
